mapper.select:
select *
from user_session
where session_id = #{sessionId}
  and status = 'ACTIVE'

  and user_id = #{userId}

limit 1

select *
from user_session
where access_jti = #{accessJti}
  and status = 'ACTIVE'

  and user_id = #{userId}

limit 1

select *
from user_session
where user_id = #{userId}
  and client_ip = #{clientIp}
  and status = 'ACTIVE'
order by last_active_at desc, login_at desc

select *
from user_session
where user_id = #{userId}
  and status = 'ACTIVE'
  and refresh_expires_at <= #{now}

select *
from user_session
where user_id = #{userId}
  and status = 'ACTIVE'
order by last_active_at desc, login_at desc
limit #{offset}, #{pageSize}

mapper.update:
update user_session
set status = #{status},
    online_status = 'OFFLINE',
    logout_at = #{logoutAt},
    expired_at = #{logoutAt},
    close_reason = 'REFRESH_EXPIRED',
    update_time = #{updateTime}
where user_id = #{userId}
  and status = 'ACTIVE'
  and refresh_expires_at <= #{logoutAt}
